import{_ as a,o as n,c as t,a0 as s}from"./chunks/framework.DoRPXVp_.js";const g=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{"title":"Architecture Overview"},"headers":[],"relativePath":"design/architecture.md","filePath":"design/architecture.md"}'),i={name:"design/architecture.md"};function r(o,e,l,p,c,d){return n(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>Lattice is composed of three core components:</p><table tabindex="0"><thead><tr><th>Component</th><th>Entry Point</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Lattice Agent</strong></td><td><code>cmd/lattice</code></td><td>Edge node: WireGuard tunnel, NATS signaling, ICE/LRP</td></tr><tr><td><strong>LatticeD</strong></td><td><code>cmd/latticed</code></td><td>All-in-one control plane: NATS + SQLite + API + UI</td></tr><tr><td><strong>Manager</strong></td><td><code>cmd/manager</code></td><td>Kubernetes operator: reconciles CRDs</td></tr></tbody></table><h2 id="transport-layer" tabindex="-1">Transport Layer <a class="header-anchor" href="#transport-layer" aria-label="Permalink to &quot;Transport Layer&quot;">​</a></h2><p>Each peer-to-peer connection goes through a state machine:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Created → Probing → ICEReady / LRPReady → Failed → Closed</span></span></code></pre></div><p>ICE (direct P2P) and LRP (relay fallback) race in parallel. Whichever establishes first wins. The connection upgrades from LRP to ICE transparently when a direct path becomes available.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Peer A                                    Peer B</span></span>
<span class="line"><span>  │  ── NATS signal ──────────────────────▶  │</span></span>
<span class="line"><span>  │  ◀── NATS signal ──────────────────────  │</span></span>
<span class="line"><span>  │                                          │</span></span>
<span class="line"><span>  │  ── ICE probe ─────────────────────────▶ │  ← races with LRP</span></span>
<span class="line"><span>  │  ── LRP connect ───────────▶ Relay ────▶ │</span></span>
<span class="line"><span>  │                                          │</span></span>
<span class="line"><span>  └─────────── WireGuard data ───────────────┘</span></span></code></pre></div><h2 id="policy-enforcement" tabindex="-1">Policy Enforcement <a class="header-anchor" href="#policy-enforcement" aria-label="Permalink to &quot;Policy Enforcement&quot;">​</a></h2><p><code>PolicyEnforcer</code> interface in <code>internal/agent/provision/provisioner.go</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SelectEnforcerMode()</span></span>
<span class="line"><span>  ├── Linux 5.10+ &amp;&amp; EDITION=pro → eBPF TC on wf0 TUN interface</span></span>
<span class="line"><span>  └── default                   → iptables</span></span></code></pre></div><p>Community edition always uses iptables. Pro edition uses eBPF when kernel supports it, with automatic fallback to iptables.</p><h2 id="agent-sandbox" tabindex="-1">Agent Sandbox <a class="header-anchor" href="#agent-sandbox" aria-label="Permalink to &quot;Agent Sandbox&quot;">​</a></h2><p>The sandbox provides a <strong>zero-privilege</strong> alternative to the regular node:</p><ul><li>Regular node: kernel TUN (<code>wf0</code>), requires <code>CAP_NET_ADMIN</code></li><li>Sandbox: gVisor <code>pkg/tcpip</code> + <code>TUNAdapter</code>, runs as any user</li></ul><p>See <a href="/design/sandbox">Sandbox Architecture</a> for the detailed design.</p><h2 id="signal-flow" tabindex="-1">Signal Flow <a class="header-anchor" href="#signal-flow" aria-label="Permalink to &quot;Signal Flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LatticeD (NATS broker)</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├── lattice.signals.peers.&lt;PeerID&gt;  ← peer signaling</span></span>
<span class="line"><span>    ├── lattice.audit.flow              ← Pro: NATS flow audit</span></span>
<span class="line"><span>    └── lattice.config.&lt;PeerID&gt;         ← peer config push</span></span></code></pre></div>`,18)])])}const u=a(i,[["render",r]]);export{g as __pageData,u as default};
